{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/matemolnar8/comprehende/src/schema/review.schema.json",
  "type": "object",
  "properties": {
    "version": {
      "type": "number",
      "const": 1
    },
    "size": {
      "type": "string",
      "enum": [
        "trivial",
        "small",
        "medium",
        "large",
        "very-large"
      ],
      "description": "Human review burden of this change."
    },
    "source": {
      "type": "object",
      "properties": {
        "baseRef": {
          "type": "string",
          "minLength": 1
        },
        "headRef": {
          "type": "string",
          "minLength": 1
        },
        "range": {
          "type": "string",
          "minLength": 1
        },
        "baseSha": {
          "type": "string",
          "minLength": 1,
          "description": "Commit baseRef resolved to when this document was written. refresh diffs from it."
        },
        "headSha": {
          "type": "string",
          "minLength": 1,
          "description": "Commit headRef resolved to when this document was written. refresh diffs from it."
        }
      },
      "required": [
        "baseRef",
        "headRef"
      ],
      "additionalProperties": false
    },
    "previous": {
      "type": "string",
      "minLength": 1,
      "description": "File name of the review this one was refreshed from, in the same directory. refresh writes it; the UI compares the two."
    },
    "title": {
      "type": "string",
      "minLength": 1,
      "description": "Short name of the whole change. Prefer a user-created title when it names this change."
    },
    "summary": {
      "type": "string",
      "minLength": 1,
      "description": "Short what of the whole change. Name the stories."
    },
    "why": {
      "type": "string",
      "minLength": 1,
      "description": "Generated why for the whole change, from tickets, issues, a request description, or a transcript. Cite sources with [text](source:id)."
    },
    "sources": {
      "description": "Locators the skill read to write its prose. Ticket bodies, PR descriptions, and transcript text stay out. PR comment body is copied.",
      "type": "array",
      "items": {
        "$ref": "#/$defs/source"
      }
    },
    "lookFor": {
      "description": "Source verdicts: a source item done differently, not done, or not true at head, manual steps a source says the change needs, and instructions a source gives a reviewer. Cite the source.",
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      }
    },
    "parts": {
      "description": "One entry per independent story when groups use part. name matches group part. summary is that story's one-sentence what.",
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "minLength": 1,
            "description": "Short name of the independent story. Same string as group part."
          },
          "summary": {
            "type": "string",
            "minLength": 1,
            "description": "One sentence: what this independent story is."
          }
        },
        "required": [
          "name",
          "summary"
        ],
        "additionalProperties": false
      }
    },
    "groups": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "minLength": 1
          },
          "title": {
            "type": "string",
            "minLength": 1
          },
          "why": {
            "type": "string",
            "minLength": 1,
            "description": "Generated why this group exists. From a source when one applies, or that it enables later groups in the same story."
          },
          "summary": {
            "type": "string",
            "description": "One sentence: what this group is."
          },
          "attention": {
            "description": "The one judgment call a reviewer makes in this group. Most groups have none.",
            "type": "object",
            "properties": {
              "kind": {
                "type": "string",
                "enum": [
                  "contract",
                  "tradeoff",
                  "product",
                  "risk"
                ],
                "description": "contract: a compatibility or API promise. tradeoff: a cost accepted for a gain. product: a product or scope call. risk: a risk accepted."
              },
              "note": {
                "type": "string",
                "minLength": 1,
                "description": "What the code at head does, where it matters, and the decision the reviewer makes."
              }
            },
            "required": [
              "kind",
              "note"
            ],
            "additionalProperties": false
          },
          "questions": {
            "description": "At most 2 questions that ask why the change is this way, where the code and the sources leave the reason open. When a source answers one, the answer goes in why.",
            "maxItems": 2,
            "type": "array",
            "items": {
              "type": "string",
              "minLength": 1
            }
          },
          "focus": {
            "description": "Ranges the UI opens a hunk to. Each sits inside one live hunk of this group and spans at most 25 lines. The whole hunk is one click away.",
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "path": {
                  "type": "string",
                  "minLength": 1,
                  "description": "Git path of a file this group covers."
                },
                "side": {
                  "type": "string",
                  "enum": [
                    "old",
                    "new"
                  ],
                  "description": "old: a line of the base file. new: a line of the head file."
                },
                "start": {
                  "type": "integer",
                  "minimum": 1,
                  "description": "First line, 1-based, on that side."
                },
                "end": {
                  "type": "integer",
                  "minimum": 1,
                  "description": "Last line, inclusive. At most 25 lines from start."
                },
                "caption": {
                  "type": "string",
                  "minLength": 1,
                  "description": "One sentence: what these lines show."
                }
              },
              "required": [
                "path",
                "side",
                "start",
                "end",
                "caption"
              ],
              "additionalProperties": false
            }
          },
          "notes": {
            "description": "Line-anchored notes the UI letters A, B, C.",
            "maxItems": 3,
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "path": {
                  "type": "string",
                  "minLength": 1,
                  "description": "Git path of a file this group covers."
                },
                "side": {
                  "type": "string",
                  "enum": [
                    "old",
                    "new"
                  ],
                  "description": "old: a line of the base file. new: a line of the head file."
                },
                "line": {
                  "type": "integer",
                  "minimum": 1,
                  "description": "1-based line on that side, inside a hunk this group covers."
                },
                "body": {
                  "type": "string",
                  "minLength": 1,
                  "description": "What the code alone does not say about this line."
                }
              },
              "required": [
                "path",
                "side",
                "line",
                "body"
              ],
              "additionalProperties": false
            }
          },
          "dependsOn": {
            "description": "Ids of earlier groups this one depends on. Same story only.",
            "type": "array",
            "items": {
              "type": "string",
              "minLength": 1
            }
          },
          "part": {
            "type": "string",
            "minLength": 1,
            "description": "Short name of the independent story this group belongs to. Same name = same story. Different names could have been separate PRs."
          },
          "sources": {
            "description": "Ids of document sources this group names, even when the prose does not cite them inline.",
            "type": "array",
            "items": {
              "type": "string",
              "minLength": 1
            }
          },
          "suggestedOrder": {
            "type": "number"
          },
          "hunkRefs": {
            "type": "array",
            "items": {
              "type": "string",
              "minLength": 1,
              "description": "A git path (every live hunk of that file), a directory ending in / (every live hunk under it), or path@oldStart+newStart. A rename is old -> new@oldStart+newStart."
            },
            "description": "A path string covers every live hunk of that file. path@oldStart+newStart is one hunk. old -> new@oldStart+newStart is a renamed hunk."
          }
        },
        "required": [
          "id",
          "title",
          "why",
          "summary",
          "suggestedOrder",
          "hunkRefs"
        ],
        "additionalProperties": false
      }
    }
  },
  "required": [
    "version",
    "size",
    "source",
    "title",
    "summary",
    "groups"
  ],
  "additionalProperties": false,
  "title": "Comprehende ReviewDocument",
  "description": "Interpretation only: title, groups, summaries, and hunk pointers.",
  "$defs": {
    "source": {
      "type": "object",
      "properties": {
        "id": {
          "type": "string",
          "minLength": 1
        },
        "kind": {
          "type": "string",
          "enum": [
            "ticket",
            "pr",
            "pr-comment",
            "commit",
            "transcript"
          ]
        },
        "label": {
          "type": "string",
          "minLength": 1,
          "description": "Short name shown in the UI. Examples: #24, alice on PR #32, Cursor session · Aug 12."
        },
        "url": {
          "type": "string",
          "minLength": 1,
          "description": "Omit for transcripts."
        },
        "title": {
          "type": "string",
          "minLength": 1
        },
        "gist": {
          "type": "string",
          "minLength": 1,
          "description": "One or two sentences, written by the skill, saying why this source matters."
        },
        "part": {
          "type": "string",
          "minLength": 1,
          "description": "Short name of the independent story this source belongs to. Same name as the groups in that story."
        },
        "author": {
          "type": "string",
          "minLength": 1,
          "description": "pr-comment only."
        },
        "body": {
          "type": "string",
          "description": "pr-comment only. The comment, faithful."
        },
        "path": {
          "type": "string",
          "minLength": 1,
          "description": "pr-comment only. Git path. With side and line, pins the comment to live git."
        },
        "side": {
          "type": "string",
          "enum": [
            "old",
            "new"
          ],
          "description": "pr-comment only. Git-shaped, not GitHub-shaped."
        },
        "line": {
          "type": "integer",
          "minimum": 1,
          "description": "pr-comment only. 1-based line on that side."
        }
      },
      "required": [
        "id",
        "kind",
        "label"
      ],
      "additionalProperties": false
    }
  }
}
